/// A form's footer.
struct Footer: View {
  @State private var busy = false
  let retries = 3

  var body: some View {
    HStack(spacing: 8) {
      TanreiButton("Cancel", variant: .text) { dismiss() }
      TanreiButton("Save") { save() }.disabled(busy)
    }
  }
}

@Composable
fun Footer(busy: Boolean, onSave: () -> Unit) {
  val retries = 3
  Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
    // one main action, one way out
    TanreiButton(onClick = onCancel, variant = ButtonVariant.Text) { Text("Cancel") }
    TanreiButton(onClick = onSave, enabled = !busy) { Text("Save") }
  }
}

class Footer extends StatelessWidget {
  const Footer({super.key, required this.busy});
  final bool busy;

  @override
  Widget build(BuildContext context) {
    return Row(children: [
      TanreiButton(label: 'Cancel', variant: TanreiButtonVariant.text),
      TanreiButton(label: 'Save', onPressed: busy ? null : save),
    ]);
  }
}

